import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int maxPoints(int[][] points) {
        int n = points.length;
        if (n <= 2) {
            return n;
        }

        int max_count = 0;

        for (int i = 0; i < n; i++) {
            Map<String, Integer> slope_map = new HashMap<>();
            int duplicates = 0;
            int local_max = 0;

            for (int j = i + 1; j < n; j++) {
                int deltaX = points[j][0] - points[i][0];
                int deltaY = points[j][1] - points[i][1];

                if (deltaX == 0 && deltaY == 0) {
                    duplicates++;
                    continue;
                }

                int g = gcd(deltaX, deltaY);
                deltaX = deltaX / g;
                deltaY = deltaY / g;

                String key = deltaX + "_" + deltaY;
                slope_map.put(key, slope_map.getOrDefault(key, 0) + 1);
                local_max = Math.max(local_max, slope_map.get(key));
            }

            max_count = Math.max(max_count, local_max + duplicates + 1);
        }

        return max_count;
    }

    private int gcd(int a, int b) {
        if (b == 0) {
            return a;
        }
        return gcd(b, a % b);
    }
}
