int lengthOfLongestSubstringTwoDistinct(string s) {
    int l = 0, r = 0, max_len = 0, cur_len = 0;
    unordered_map<char, int> char_count;

    while (r < s.length()) {
        char_count[s[r]]++;
        if (char_count.size() <= 2) {
            cur_len++;
        } else {
            while (char_count.size() > 2 && l <= r) {
                char_count[s[l]]--;
                if (char_count[s[l]] == 0) {
