        if (!deque.isEmpty() && deque.peekFirst() == i - k) deque.poll();

        while (!deque.isEmpty() && nums[deque.peekLast()] < nums[i]) {
            deque.removeLast();
        }    

        deque.offer(i);
        if (i >= k - 1) {
            result[idx++] = nums[deque.peek()];
        }
    }
    return result;
}
