            int i = curr[0];
            int j = curr[1];

            for(int[] d : directions) {
                int ni = i + d[0];
                int nj = j + d[1];

                if(ni >= 0 && ni < m && nj >= 0 && nj < n && rooms[ni][nj] == INF) {
                    rooms[ni][nj] = rooms[i][j] + 1;
                    q.add(new int[]{ni, nj});
                }
            }
        }
