```java
import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static List<Integer> countSmaller(int[] nums) {
        List<Integer> counts = new ArrayList<>();
        for (int i = 0; i < nums.length; i++) {
            counts.add(0);
        }
        mergeSort(nums, 0, nums.length - 1, counts);
        return counts;
    }

    private static void mergeSort(int[] nums, int start, int end, List<Integer> counts) {
        if (start >= end) {
            return;
        }
        int mid = start + (end - start) / 2;
        mergeSort(nums, start, mid, counts);
        mergeSort(nums, mid + 1, end, counts);
        merge(nums, start, mid, end, counts);
    }

    private static void merge(int[] nums, int start, int mid, int end, List<Integer> counts) {
        int[] temp = new int[end - start + 1];
        int i = start, j = mid + 1, k = 0;
        while (i <= mid && j <= end) {
            if (nums[i] <= nums[j]) {
                counts.set(i, counts.get(i) + (j - mid - 1));
                temp[k++] = nums[i++];
            } else {
                temp[k++] = nums[j++];
            }
        }
        while (i <= mid) {
            counts.set(i, counts.get(i) + (j - mid - 1));
            temp[k++] = nums[i++];
        }
        while (j <= end) {
            temp[k++] = nums[j++];
        }
        for (int p = 0; p < temp.length; p++) {
            nums[start + p] = temp[p];
        }
    }

    public static void main(String[] args) {
        int[] nums = {5, 2, 6, 1};
        List<Integer> result = countSmaller(nums);
        System.out.println(result);
    }
}
