public class Solution {
    public int countRangeSum(int[] nums, int lower, int upper) {
        int[] sums = new int[nums.length + 1];
        for (int i = 0; i < nums.length; i++) {
            sums[i + 1] = sums[i] + nums[i];
        }

        return mergeSort(sums, 0, nums.length, lower, upper);
    }

    private int mergeSort(int[] sums, int start, int end, int lower, int upper) {
        if (start == end) {
            return 0;
        }
        int mid = start + (end - start) / 2;
        int count = mergeSort(sums, start, mid, lower, upper) + mergeSort(sums, mid + 1, end, lower, upper);

        int j = mid + 1;
        int k = mid + 1;
        for (int i = start; i <= mid; i++) {
            while (j <= end && sums[j] - sums[i] < lower) {
                j++;
            }
            while (k <= end && sums[k] - sums[i] <= upper) {
                k++;
            }
            count += k - j;
        }

        Arrays.sort(sums, start, end + 1);
        return count;
    }
}
