        int start = 0;
        int end = s.indexOf(delimiter);
        while (end != -1) {
            subs.add(s.substring(start, end));
            start = end + 1;
            end = s.indexOf(delimiter, start);
        }
        subs.add(s.substring(start));
        return subs;
    }

