        pq.push({heightMap[0][i], {0, i}});
        pq.push({heightMap[m - 1][i], {m - 1, i}});
        visited[0][i] = visited[m - 1][i] = true;
    }

    int water = 0, maxHeight = 0;
    vector<pair<int, int>> dirs = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};

    while (!pq.empty()) {
        auto [h, r, c] = pq.top();
        pq.pop();
        maxHeight = max(maxHeight, h);
        for (auto [dx, dy] : dirs) {
