import java.util.PriorityQueue;

public class Solution {
    public static int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        int[][] projectPool = new int[profits.length][2];
        for (int i = 0; i < profits.length; i++) {
            projectPool[i][0] = capital[i];
            projectPool[i][1] = profits[i];
        }
        Arrays.sort(projectPool, (a, b) -> b[0] - a[0]);

        PriorityQueue<Integer> profitPool = new PriorityQueue<>(Collections.reverseOrder());

        while (k > 0) {
            while (projectPool.length > 0 && projectPool[projectPool.length - 1][0] <= w) {
                profitPool.add(-projectPool[projectPool.length - 1][1]);
                projectPool = Arrays.copyOfRange(projectPool, 0, projectPool.length - 1);
