#include <iostream>
#include <vector>
#include <unordered_map>
#include <sstream>

std::vector<std::vector<std::string>> find_duplicate(std::vector<std::string>& paths) {
    std::unordered_map<std::string, std::vector<std::string>> content_map;
    for (const auto& path : paths) {
        std::istringstream iss(path);
        std::string directory;
        iss >> directory;
        std::string file;
        while (iss >> file) {
            size_t start = file.find('(');
            size_t end = file.find(')');
            std::string content = file.substr(start + 1, end - start - 1);
            std::string file_path = directory + '/' + file.substr(0, start);
            content_map[content].push_back(file_path);
        }
    }

    std::vector<std::vector<std::string>> result;
    for (const auto& pair : content_map) {
        if (pair.second.size() > 1) {
            result.push_back(pair.second);
        }
    }
    return result;
}

int main() {
    std::vector<std::string> paths = {"root/a 1.txt(abcd) 2.txt(efgh)", "root/c 3.txt(abcd)", "root/c/d 4.txt(efgh)", "root 4.txt(efgh)"};
    std::vector<std::vector<std::string>> result = find_duplicate(paths);
    for (const auto& group : result) {
        for (const auto& file_path : group) {
            std::cout << file_path << " ";
        }
        std::cout << std::endl;
    }
    return 0;
}
