#include <vector>
#include <algorithm>

using namespace std;

int shoppingOffers(vector<int>& price, vector<vector<int>>& special, vector<int>& needs) {
    int n = price.size();
    int m = special.size();

    vector<int> dp(needs.begin(), needs.end());

    for (int i = 0; i < m; i++) {
        vector<int> offer = special[i];
        int offerCost = offer.back();
        offer.pop_back();

        bool canApplyOffer = true;
        for (int j = 0; j < n; j++) {
            if (needs[j] < offer[j]) {
                canApplyOffer = false;
                break;
            }
        }

        if (canApplyOffer) {
            for (int j = 0; j < n; j++) {
                needs[j] -= offer[j];
            }
            int withOffer = offerCost + shoppingOffers(price, special, needs);
            for (int j = 0; j < n; j++) {
                needs[j] += offer[j];
            }
            dp[i] = min(dp[i], withOffer);
        }
    }

    int noOffer = 0;
    for (int i = 0; i < n; i++) {
        noOffer += needs[i] * price[i];
    }

    return min(noOffer, dp[m - 1]);
}

int main() {
    vector<int> price = {2, 5};
    vector<vector<int>> special = {{3, 0, 5}, {1, 2, 10}};
    vector<int> needs = {3, 2};

    int result = shoppingOffers(price, special, needs);
    cout << result << endl;  // Output: 14

    return 0;
}
