    int[] sums = new int[n - k + 1];
    int[] left = new int[n], right = new int[n], ans = new int[3];
    int acc_sum = 0;

    for (int i = 0; i < n; ++i) {
        acc_sum += nums[i];
        if (i >= k) {
            acc_sum -= nums[i - k];
        }
        if (i >= k - 1) {
