public class Solution {
    public int monotoneIncreasingDigits(int n) {
        String n_str = Integer.toString(n);
        int n_len = n_str.length();

        int i = n_len - 1;
        while (i > 0) {
            if (n_str.charAt(i) < n_str.charAt(i - 1)) {
                n_str = n_str.substring(0, i - 1) + (n_str.charAt(i - 1) - 1) + n_str.substring(i);
                for (int j = i; j < n_len; ++j) {
                    n_str = n_str.substring(0, j) + '9' + n_str.substring(j + 1);
