import heapq

def networkDelayTime(times, n, k):
    graph = {}
    for u, v, w in times:
        graph.setdefault(u, []).append((v, w))

    dist = [float('inf')] * (n + 1)
    dist[k] = 0

    pq = [(0, k)]
    while pq:
        curr_dist, u = heapq.heappop(pq)
        if curr_dist > dist[u]:
