        for v, weight in graph.get(u, []):
            if curr_dist + weight < dist[v]:
                dist[v] = curr_dist + weight
                heapq.heappush(pq, (dist[v], v))

    max_time = max(dist[1:])
    return max_time if max_time != float('inf') else -1

