import java.util.HashMap;
import java.util.List;
import java.util.ArrayList;

public class PyramidTransition {
    public static boolean pyramidTransition(String bottom, List<String> allowed) {
        HashMap<String, List<Character>> mapping = new HashMap<>();
        for (String s : allowed) {
            String key = s.substring(0, 2);
            if (!mapping.containsKey(key)) {
                mapping.put(key, new ArrayList<>());
            }
            mapping.get(key).add(s.charAt(2));
        }
        return pyramidTransitionHelper(bottom, "", 0, mapping);
