            return true;
        }
        if (idx == bottom.length() - 1) {
            return pyramidTransitionHelper(top, "", 0, mapping);
        }
        String key = bottom.substring(idx, idx + 2);
        if (!mapping.containsKey(key)) {
            return false;
        }
        for (char c : mapping.get(key)) {
            if (pyramidTransitionHelper(bottom, top + c, idx + 1, mapping)) {
