        while (!stack.isEmpty()) {
            Pair<Character, Integer> pair = stack.pop();
            for (int i = 0; i < pair.getValue(); i++) {
                sb.append(pair.getKey());
            }
        }
        return sb.reverse().toString();
    }
}
