import java.util.Arrays;
import java.util.Comparator;

public class JobScheduling {
    public static int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        int[][] jobs = new int[startTime.length][3];
        for (int i = 0; i < startTime.length; i++) {
            jobs[i][0] = endTime[i];
            jobs[i][1] = startTime[i];
            jobs[i][2] = profit[i];
        }
        Arrays.sort(jobs, Comparator.comparingInt(a -> a[0]));

        int[] dp = new int[jobs.length];
        dp[0] = jobs[0][2];

        for (int i = 1; i < jobs.length; i++) {
            int L = latestNonConflict(jobs, i);
            dp[i] = Math.max(dp[i - 1], (L == -1 ? 0 : dp[L]) + jobs[i][2]);
        }

        return dp[jobs.length - 1];
    }

    private static int latestNonConflict(int[][] jobs, int index) {
        int startTimeToFind = jobs[index][1];
        int left = 0, right = index - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (jobs[mid][0] <= startTimeToFind) {
                if (jobs[mid + 1][0] > startTimeToFind) {
                    return mid;
                }
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
        return -1;
    }

