        int[] startTime = {1, 2, 3, 3};
        int[] endTime = {3, 4, 5, 6};
        int[] profit = {50, 10, 40, 70};
        System.out.println(jobScheduling(startTime, endTime, profit)); // Output: 120
    }
}
