int shortestPath(vector<vector<int>>& grid, int k) {
    int m = grid.size(), n = grid[0].size();
    vector<vector<vector<bool>>> visited(m, vector<vector<bool>>(n, vector<bool>(k + 1, false)));
    queue<vector<int>> q;
    q.push({0, 0, 0, k});
    vector<vector<int>> moves = {{0, 1}, {0, -1}, {1, 0}, {-1, 0}};
    int steps = 0;

    while (!q.empty()) {
        int size = q.size();
        for (int i = 0; i < size; i++) {
            int x = q.front()[0], y = q.front()[1], steps = q.front()[2], k_remaining = q.front()[3];
            q.pop();
            if (x == m - 1 && y == n - 1) {
                return steps;
            }
            for (auto& move : moves) {
                int new_x = x + move[0], new_y = y + move[1];
                if (new_x >= 0 && new_x < m && new_y >= 0 && new_y < n) {
                    int new_k_remaining = k_remaining - grid[new_x][new_y];
                    if (new_k_remaining >= 0 && !visited[new_x][new_y][new_k_remaining]) {
                        visited[new_x][new_y][new_k_remaining] = true;
                        q.push({new_x, new_y, steps + 1, new_k_remaining});
                    }
                }
            }
        }
        steps++;
    }

    return -1;
