import java.util.*;

public class Solution {
    public static int minJumps(int[] arr) {
        int n = arr.length;
        if (n <= 1) return 0;

        Map<Integer, List<Integer>> valueIndices = new HashMap<>();
        for (int i = 0; i < n; ++i) {
            valueIndices.computeIfAbsent(arr[i], k -> new ArrayList<>()).add(i);
        }

        Queue<Integer> q = new LinkedList<>();
        boolean[] visited = new boolean[n];

        q.offer(0);
        visited[0] = true;
        int steps = 0;

        while (!q.isEmpty()) {
            int size = q.size();

            for (int i = 0; i < size; ++i) {
                int index = q.poll();

                if (index == n - 1) return steps;

                if (index > 0 && !visited[index - 1]) {
                    q.offer(index - 1);
                    visited[index - 1] = true;
                }

                if (index < n - 1 && !visited[index + 1]) {
                    q.offer(index + 1);
                    visited[index + 1] = true;
                }

                for (int neighbor : valueIndices.getOrDefault(arr[index], Collections.emptyList())) {
                    if (!visited[neighbor]) {
                        q.offer(neighbor);
                        visited[neighbor] = true;
                    }
                }

                valueIndices.getOrDefault(arr[index], Collections.emptyList()).clear();
            }

            ++steps;
        }

        return -1;
    }

