    } else {
        if (!mod[2].empty()) {
            mod[2].pop_back();
        } else {
            mod[1].pop_back();
            mod[1].pop_back();
        }
    }

    std::string result;
    for (auto& pair : mod) {
        for (int digit : pair.second) {
            result += std::to_string(digit);
        }
    }
