import java.util.PriorityQueue;

public class Solution {
    public int maxSum(int[] nums, int k) {
        int n = nums.length;
        PriorityQueue<Integer> pq = new PriorityQueue<>((a, b) -> b - a);
        long[] dp = new long[n + 1];
        long sum = 0;

        for (int i = 0; i < n; ++i) {
            if (i >= k) pq.poll(); // Maintain the maximum size of k
