public int minSetSize(int[] arr) {
    HashMap<Integer, Integer> count = new HashMap<>();
    for (int value : arr)
        count.put(value, count.getOrDefault(value, 0) + 1);

    ArrayList<Integer> freq = new ArrayList<>(count.values());
