std::vector<int> findPath(int n, std::vector<std::vector<int>>& roads, std::vector<std::string>& names, std::vector<std::string>& targetPath) {
    std::unordered_map<std::string, int> nameToIndex;
    for (int i = 0; i < n; i++) {
        nameToIndex[names[i]] = i;
    }

    std::vector<std::vector<int>> graph(n);
    for (const auto& road : roads) {
        graph[road[0]].push_back(road[1]);
        graph[road[1]].push_back(road[0]);
    }

    std::vector<int> path;
    std::vector<bool> visited(n, false);
    std::vector<int> parent(n, -1);

    for (int i = 0; i < n; i++) {
        if (!visited[i]) {
            dfs(graph, visited, parent, i);
        }
    }

    int targetIndex = nameToIndex[targetPath.back()];
    if (parent[targetIndex] == -1) {
        return {};
    }

    int current = targetIndex;
    while (current != -1) {
        path.push_back(current);
        current = parent[current];
    }

    std::reverse(path.begin(), path.end());
    return path;
}

void dfs(const std::vector<std::vector<int>>& graph, std::vector<bool>& visited, std::vector<int>& parent, int node) {
