public class Solution {
    public int numWays(String s) {
        int number_of_ones = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '1') {
                number_of_ones++;
            }
        }
        if (number_of_ones % 3 != 0) {
            return 0;
        }

        int target = number_of_ones / 3;
        if (target == 0) {
            int n = s.length();
            return ((n - 1) * (n - 2) / 2) % 1000000007;
        }

        int ones_so_far1 = 0, ones_so_far2 = 0;
        int way1 = 0, way2 = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == '1') {
                ones_so_far1++;
                if (ones_so_far1 == target) {
                    way1++;
                    ones_so_far1 = 0;
                }

                ones_so_far2++;
                if (ones_so_far2 == target * 2) {
                    way2++;
                    ones_so_far2 = 0;
                }
            }
        }

        return (way1 * way2) % 1000000007;
    }
}
