int minMoves(std::vector<int>& nums, int k) {
    std::vector<int> ones_pos;
    for (int i = 0; i < nums.size(); ++i) {
        if (nums[i] == 1) {
            ones_pos.push_back(i);
        }
    }

    std::vector<int> to_move;
    for (int i = 0; i < k; ++i) {
        to_move.push_back(ones_pos[i] - i);
    }

    int min_moves = 0;
    for (int i = k; i < ones_pos.size(); ++i) {
        to_move.push_back(ones_pos[i] - ones_pos[i - k]);
    }

    min_moves = std::accumulate(to_move.begin() + k / 2, to_move.end(), 0);

    int move = min_moves;
    for (int i = k; i < ones_pos.size() - k; ++i) {
        move += to_move[i] - to_move[i - k];
        min_moves = std::min(min_moves, move);
    }

    return min_moves;
}

