using namespace std;

class TrieNode {
public:
    unordered_map<int, TrieNode*> children;
    bool isEnd;

    TrieNode() {
        isEnd = false;
    }
};

class Trie {
public:
    TrieNode* root;

    Trie() {
        root = new TrieNode();
    }

    void insert(int num) {
        TrieNode* cur = root;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (cur->children.find(bit) == cur->children.end()) {
                cur->children[bit] = new TrieNode();
            }
            cur = cur->children[bit];
        }
        cur->isEnd = true;
    }

    int getMaxXor(int num) {
        TrieNode* cur = root;
        int xorValue = 0;
        for (int i = 31; i >= 0; i--) {
            int bit = (num >> i) & 1;
            if (cur->children.find(1 ^ bit) != cur->children.end()) {
                cur = cur->children[1 ^ bit];
                xorValue |= 1 << i;
            } else {
                cur = cur->children[bit];
            }
        }
        return xorValue;
    }
};

