public class Solution {
    public int makeStringSorted(String s) {
        int mod = 1000000007;
        int n = s.length();
        int[] fact = new int[n + 1];
        int[] inv = new int[n + 1];
        fact[0] = 1;
        inv[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int)((long)fact[i - 1] * i % mod);
            inv[i] = (int)((long)inv[i - 1] * (mod - mod / i) % mod);
