import java.util.*;

public class MaxNodesWithoutRestricted {
    public static int maxNodesWithoutRestricted(int n, int[][] edges, int[] restricted) {
        Map<Integer, List<Integer>> tree = new HashMap<>();
        Set<Integer> blockedNodes = new HashSet<>();
        for (int i = 0; i < restricted.length; i++) {
            blockedNodes.add(restricted[i]);
        }

        for (int[] edge : edges) {
            tree.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
            tree.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
        }

        int[] maxNodes = new int[1];
        maxNodes[0] = 0;

        dfs(0, 1, -1, tree, blockedNodes, maxNodes);

        return maxNodes[0];
    }

