import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static boolean canEqualFrequency(String word) {
        Map<Character, Integer> freq = new HashMap<>();
        for (char c : word.toCharArray()) {
            freq.put(c, freq.getOrDefault(c, 0) + 1);
        }

        Map<Integer, Integer> countFreq = new HashMap<>();
        for (int f : freq.values()) {
            countFreq.put(f, countFreq.getOrDefault(f, 0) + 1);
        }

        if (countFreq.size() != 2) {
            return false;
        }

        int a = 0, acount = 0;
        int b = 0, bcount = 0;
        for (Map.Entry<Integer, Integer> entry : countFreq.entrySet()) {
            if (a == 0) {
                a = entry.getKey();
                acount = entry.getValue();
            } else {
                b = entry.getKey();
                bcount = entry.getValue();
            }
        }

        return (acount == 1 && (a - 1 == b || a == 1)) || (bcount == 1 && (b - 1 == a || b == 1));
    }

