import java.util.Arrays;

public class Solution {
    public static int minValidSubarrays(int[] nums) {
        int count = 0;
        for (int i = 0; i < nums.length; i++) {
            while (i < nums.length && gcd(nums[i], nums[nums.length - 1]) == 1) {
                i++;
            }
