public class Solution {
    public static int concatenationValue(int[] nums) {
        int value = 0;
        while (nums.length > 0) {
            int n = nums.length;
            if (n == 1) {
                value += nums[0];
                nums = removeElement(nums, 0);
            } else {
                value += Integer.parseInt(String.valueOf(nums[0]) + String.valueOf(nums[n - 1]));
                nums = removeElements(nums, 0, n - 1);
            }
        }
