            node = q.popleft()
            level_sum += node.val

            if node.left:
                q.append(node.left)
            if node.right:
                q.append(node.right)

        heapq.heappush(level_sums, -level_sum)

    if k > len(level_sums):
        return -1
    return -heapq.heappop(level_sums)
