from typing import List
from collections import deque

def shortestCycleLength(n: int, edges: List[List[int]]) -> int:
    graph = [[] for _ in range(n)]
    for edge in edges:
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])

    shortestCycle = n + 1
    for start in range(n):
        dist = [n + 1] * n
        dist[start] = 0
        queue = deque([start])

        while queue:
            cur = queue.popleft()
            for neigh in graph[cur]:
                if dist[neigh] == n + 1:
                    dist[neigh] = dist[cur] + 1
                    queue.append(neigh)
                elif dist[neigh] >= dist[cur] - 1:
                    shortestCycle = min(shortestCycle, dist[cur] + dist[neigh] + 1)

    return -1 if shortestCycle == n + 1 else shortestCycle

