import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.Arrays;
import java.util.StringTokenizer;

public class Solution {
    private static int n, d;
    private static int[] arr = new int[30001];
    private static int[][] res = new int[30001][500];
    private static int get(int curr, int jump) {
        if (curr>30000) return 0;
        if (res[curr][jump-d+250]!=-1) return res[curr][jump-d+250];
        int result = get(curr + jump, jump);
        if (jump>1) result = Math.max(result, get(curr + jump - 1, jump - 1));
        result = Math.max(result, get(curr + jump + 1, jump + 1));
        result+=arr[curr];
        res[curr][jump-d+250] = result;
        return result;
    }
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer sToken = new StringTokenizer(reader.readLine());
        n = Integer.parseInt(sToken.nextToken());
        d = Integer.parseInt(sToken.nextToken());
        for (int i=0; i<n; i++) arr[Integer.parseInt(reader.readLine())]++;
        for (int i=0; i<=30000; i++) Arrays.fill(res[i], -1);
        System.out.println(get(d, d));
    }
}

