function countingValleys(steps, path) {
  // Write your code here
  let count = 0;
  let level = 0;
  for (let i = 0; i < steps; i++) {
    if (path[i] === 'U') {
      level++;
      if (level === 0) {
        count++;
      }
    } else {
      level--;
    }
  }
  return count;
}

