int main() {
    int t = 1;
    for (int test = 0; test < t; test++) {
        int n;
        cin >> n;
        vector<int> p(n+1);
        vector<int> s(n+1);
        vector<int> a(n+1, 0);
        a[1] = s[1] = 0;
        unordered_map<int, vector<int>> D;
        unordered_map<int, int> depth;
        depth[1] = 1;
        for (int i = 2; i <= n; i++) {
            cin >> p[i];
            D[p[i]].push_back(i);
            depth[i] = depth[p[i]] + 1;
        }
        queue<int> q;
        q.push(1);
        bool found = true;
        while (!q.empty()) {
            int cur = q.front();
            q.pop();
            if (!found) {
                break;
            }
            for (int j : D[cur]) {
                if (depth[j] % 2 == 0) {
                    if (D[j].empty()) {
                        a[j] = 0;
                        s[j] = s[cur];
                    } else {
                        int tmp = 2000000000;
                        for (int k : D[j]) {
                            tmp = min(tmp, s[k] - s[cur]);
                        }
                        if (tmp < 0) {
                            found = false;
                            break;
                        }
                        a[j] = tmp;
                        s[j] = s[cur] + tmp;
                        for (int k : D[j]) {
                            a[k] = s[k] - tmp - s[cur];
                        }
                    }
                } else {
                    if (a[k] < 0) {
                        found = false;
                        break;
                    }
                }
                q.push(j);
            }
        }
        if (found) {
            int sum = 0;
            for (int i = 1; i <= n; i++) {
                sum += a[i];
            }
            cout << sum << endl;
        } else {
            cout << -1 << endl;
        }
    }
    return 0;
}
