		Arrays.sort(a);
		Arrays.sort(b);
		int m = 1;
		for(int i=0;i<k-1;i++) if(a[i+1]>a[i]) m++;

		int[] seq = new int[m];
		int j=1;
		seq[0] = a[0];
		for(int i=0;i<k-1;i++) if(a[i+1]>a[i]) seq[j++] = a[i+1];
		return search(seq, b);
