# Function to check if a string is a palindrome
is_palindrome() {
    local str=$1
    local len=${#str}
    local i j

    for ((i=0, j=len-1; i<j; i++, j--)); do
        if [ "${str:$i:1}" != "${str:$j:1}" ]; then
            return 1 # Not a palindrome
        fi
    done

    return 0 # Palindrome
}

# Function to find the longest palindromic substring
longest_palindrome() {
    local str=$1
    local len=${#str}
    local i j k

    for ((i=0; i<len; i++)); do
        for ((j=i+1; j<=len; j++)); do
            local substr=${str:i:j-i}
            if is_palindrome "$substr"; then
                if [ ${#substr} -gt ${#longest} ]; then
                    longest=$substr
                fi
            fi
        done
    done
}

