# Function to check if a string is a palindrome
is_palindrome() {
    local str=$1
    local len=${#str}
    local mid=$((len / 2))
    local i=0

    while [ $i -lt $mid ]; do
        if [ "${str:$i:1}" != "${str:$(($len - $i - 1)):1}" ]; then
            return 1 # Not a palindrome
        fi
        ((i++))
    done

    return 0 # Palindrome
}

