import sys
from typing import List, Tuple

def get_dst(u: int, v: int, arr: List[Tuple[int, int]]) -> int:
    return (arr[u][0] - arr[v][0]) * (arr[u][0] - arr[v][0]) + (arr[u][1] - arr[v][1]) * (arr[u][1] - arr[v][1])

def get_far(pre: int, arr: List[Tuple[int, int]], chk: List[bool]) -> int:
    res = pre
    for i in range(1, len(arr)):
        if chk[i]:
            continue
        if get_dst(pre, res, arr) < get_dst(pre, i, arr):
            res = i
    return res

def main():
    n = int(input())
    arr = []
    for _ in range(n):
        x, y = map(int, input().split())
        arr.append((x, y))
    chk = [False] * n
    pre = 0
    chk[pre] = True
    print(pre + 1, end=" ")
    for _ in range(1, n):
        curr = get_far(pre, arr, chk)
        print(curr + 1, end=" ")
        chk[pre = curr] = True
    print()

if __name__ == "__main__":
    main()
