#include <string>
#include <sstream>
#include <vector>

std::string reverseWords(std::string s) {
    std::istringstream iss(s);
    std::vector<std::string> words;
    std::string word;
    while (iss >> word) {
        words.push_back(word);
    }
    std::string reversed;
    for (int i = words.size() - 1; i >= 0; i--) {
        reversed += words[i];
        if (i > 0) {
            reversed += " ";
        }
    }
    return reversed;
}
