import sys
from collections import defaultdict

class FAST:
    def __init__(self):
        self.inp = sys.stdin
        self.str = None

    def next(self):
        while self.str is None or not self.str:
            try:
                self.str = self.inp.readline().split()
            except:
                return None
        return self.str.pop(0)

    def nextInt(self):
        return int(self.next())

    def nextLong(self):
        return int(self.next())

    def nextLine(self):
        return self.inp.readline().strip()

