			return;
		}
		int[] x = new int[n];
		int sum = 0;
		for (int i = 0; i < n; i++) {
			x[i] = in.nextInt();
			sum += x[i];
		}
		int maxCnt = n * m;
		double[][] p = new double[n + 1][maxCnt + 1];
		p[0][0] = 1;
		for (int i = 0; i < n; i++) {
			double cur = 0;
			for (int j = 1; j <= maxCnt; j++) {
				cur += p[i][j - 1];
				if (j > m) {
					cur -= p[i][j - m - 1];
				}
				if (j >= x[i]) {
					cur -= p[i][j - x[i]];
				}

				p[i + 1][j] += cur / (m - 1);

				if (j >= x[i]) {
					cur += p[i][j - x[i]];
				}
			}
		}
		double pp = 0;
