std::vector<bool> prime;

void SieveOfEratosthenes() {
    int n = 6000;
    prime.resize(n + 1, true);
    int p = 2;
    while (p * p <= n) {
        if (prime[p]) {
            for (int i = p * p; i <= n; i += p) {
                prime[i] = false;
            }
        }
        p++;
