            A[n] = in.nextInt();
        }
        StringBuilder output = new StringBuilder();
        int downIdx = 0;
        int upIdx = N-1;
        int last = 0;
        while (downIdx <= upIdx) {
            int down = A[downIdx];
            int up = A[upIdx];
            if (down > last) {
                if (up > last) {
                    if (down < up) {
                        last = down;
                        downIdx++;
                        output.append('L');                        
                    } else if (down > up) {
                        last = up;
                        upIdx--;
