import java.io.*;
import java.math.*;
import java.util.*;

public class B {
    private void solve() throws IOException {
        int n = nextInt();      
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        int[] r = a.clone();
        int res = 0;
        boolean enter = false;
        int i1 = -1;
        int j1 = -1;

        for (int i = 0; i < a.length; i++) {
            for (int j = 0; j < a.length; j++) {
                if (i == j)
                    continue;
                if (Math.abs(a[i] - a[j]) > 0) {
                    res = Math.abs(a[i] - a[j]) / 2;
                    if (a[i] < a[j]) {
                        a[i] += res;
                        a[j] -= res;
                        i1 = i;
                        j1 = j;
                    } else {
                        i1 = j;
                        j1 = i;
                        a[i] -= res;
                        a[j] += res;
                    }
                    enter = true;
                    Set<Integer> s = new HashSet<Integer>();
                    for (int L = 0; L < a.length; L++) {
                        s.add(a[L]);
                    }
                    if (s.size() == 1 && i1 != -1 &&  j1 != -1) {
                        System.out.printf("%d ml. from cup #%d to cup #%d.\n",
                                res, i1+1, j1+1);
                        return;
                    }
                    i1 = -1;
                    j1 = -1;
                    reset(a , r);
                }
            }
        }

        if (!enter) {
            System.out.println("Exemplary pages.");
            return;
        }
        System.out.println("Unrecoverable configuration.");
    }

    private void reset(int[] a , int [] r) {
        for (int i = 0; i < r.length; i++) {
            a[i] = r[i];
        }
    }

    public static void main(String[] args) {
        new B().run();
    }

    BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter writer;

    public void run() {
        try {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
            writer = new PrintWriter(System.out);
            solve();
            reader.close();
            writer.close();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    int[] readIntArray(int size) throws IOException {
        int[] res = new int[size];
        for (int i = 0; i < size; i++) {
            res[i] = nextInt();
        }
        return res;
    }

    long[] readLongArray(int size) throws IOException {
        long[] res = new long[size];
        for (int i = 0; i < size; i++) {
            res[i] = nextLong();
        }
        return res;
    }

    double[] readDoubleArray(int size) throws IOException {
        double[] res = new double[size];
        for (int i = 0; i < size; i++) {
            res[i] = nextDouble();
        }
        return res;
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    BigInteger nextBigInteger() throws IOException {
        return new BigInteger(nextToken());
    }

    String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }
}


