def translate_code(input_str):
    lines = input_str.split('\n')
    translated_lines = []
    for line in lines:
        if line.startswith('#include'):
            continue
        elif line.startswith('using namespace'):
            continue
        elif line.startswith('int main()'):
            translated_lines.append('def main():')
        elif line.startswith('ios_base::sync_with_stdio(0);'):
            continue
        elif line.startswith('int n, m;'):
            translated_lines.append('n, m = map(int, input().split())')
        elif line.startswith('vector<int> val(n);'):
            translated_lines.append('val = list(map(int, input().split()))')
        elif line.startswith('int a, b;'):
            continue
        elif line.startswith('long long res = 0;'):
            translated_lines.append('res = 0')
        elif line.startswith('for (int i = 0; i < m; ++i) {'):
            translated_lines.append('for i in range(m):')
        elif line.startswith('cin >> a >> b;'):
            translated_lines.append('a, b = map(int, input().split())')
        elif line.startswith('long long t = 0;'):
            translated_lines.append('t = 0')
        elif line.startswith('for (int j = a - 1; j < b; ++j) t += val[j];'):
            translated_lines.append('for j in range(a - 1, b): t += val[j]')
        elif line.startswith('if (t > 0) res += t;'):
            translated_lines.append('if t > 0: res += t')
        elif line.startswith('cout << res << endl;'):
            translated_lines.append('print(res)')
        elif line.startswith('return 0;'):
            continue
        else:
            translated_lines.append(line)
    return '\n'.join(translated_lines)

