import sys
from typing import List

def less(val: int) -> int:
    ans = 0
    while val > 0:
        ans += bit[val]
        val -= val & (-val)
    return ans

def read(b: int, a: int) -> int:
    return less(a) - less(b - 1)

def update(idx: int, max_val: int) -> None:
    while idx <= max_val:
        bit[idx] += 1
        idx += idx & (-idx)

def main():
    n = int(input())
    bit = [0] * (n + 1)
    array = [Point(float('inf'), 0)]
    array.extend(Point(int(x), i) for i, x in enumerate(input().split(), start=1))
    array.sort(key=lambda p: (p.x, p.y))
    ans = [0] * n

    for i in range(1, n + 1):
        idx = array[i].y
        for j in range(1, n):
            if (idx - 1) * j + 2 > n:
                break
            ans[j] += read((idx - 1) * j + 2, min(n, idx * j + 1))
        update(idx, n)

    print(' '.join(str(x) for x in ans[:-1]))

if __name__ == "__main__":
    main()
