            for (int v : g[u]) {
                if (!usedEdge.count(convert(u, v))) {
                    usedEdge.insert(convert(u, v));
                    usedEdge.insert(convert(v, u));
                    q.push(v);
                }
            }

            int prev = -1;
            while (!q.empty()) {
                int v = q.front();
                q.pop();
                int rest = dfs(v);

