vector<int> solve(int n, int l, int r) {
    // 1, 2, 1, 3, ..., 1, n
    // 2, 3, 2, 4, ..., 2, n
    // ...
    // n-1, n
    // 1

    int lo = 1, hi = n;
    while (lo <= hi) {
        int k = (lo + hi) / 2;
        int s = k * (2*n-1-k);
        if (s < l) {
            lo = k + 1;
        } else {
            hi = k - 1;
        }
    }

    int k = lo;
    int s = k * (2*n-1-k);
    int b = k;

    // [b, b+1, b, b+2, ..., b, n]
    vector<int> row;
    for (int i = b+1; i <= n; i++) {
        row.push_back(b);
        row.push_back(i);
    }
    vector<int> ans = vector<int>(row.begin() + l-s-1, row.end());
    int d = r-l+1;
    if (ans.size() >= d) {
        return vector<int>(ans.begin(), ans.begin()+d);
    }

    while (ans.size() < d) {
        b += 1;
        row.clear();
        for (int i = b+1; i <= n; i++) {
            row.push_back(b);
            row.push_back(i);
        }
        if (row.empty()) {
            break;
        }
        ans.insert(ans.end(), row.begin(), row.end());
    }

    ans.push_back(1);
    return vector<int>(ans.begin(), ans.begin()+d);
}

