import java.util.*;

public class Main {
    static final int maxn = 3000 + 50;
    static List<Integer>[] edge = new ArrayList[maxn];
    static int[][] sub = new int[maxn][maxn];
    static int[][] fa = new int[maxn][maxn];
    static long n, ans;
    static long[][] dp = new long[maxn][maxn];

    static void dfs(int root, int k, int dad) {
        sub[root][k]++;
        fa[root][k] = dad;
        for (int t : edge[k]) {
            if (t != dad) {
                dfs(root, t, k);
                sub[root][k] += sub[root][t];
            }
        }
    }

    static long DP(int a, int b) {
        if (a == b) return 0;
        if (dp[a][b] != -1) return dp[a][b];
        return dp[a][b] =
                sub[a][b] * sub[b][a] + Math.max(DP(fa[a][b], a), DP(fa[b][a], b));
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        n = scanner.nextLong();
        for (int i = 1; i <= n; i++) {
            edge[i] = new ArrayList<>();
        }
        for (int i = 1; i < n; i++) {
            int u = scanner.nextInt();
            int v = scanner.nextInt();
            edge[u].add(v);
            edge[v].add(u);
        }
        for (int i = 1; i <= n; i++) {
            dfs(i, i, -1);
        }
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (i != j) {
                    ans = Math.max(ans, DP(i, j));
                }
            }
        }
        System.out.println(ans);
    }
}
