from collections import defaultdict

def dfs(graph, L, a):
    if L[a] != 0:
        return L[a]
    resp = 0
    for x in graph[a]:
        if a > x:
            resp = max(dfs(graph, L, x), resp)
    L[a] = resp + 1
    return L[a]

def main():
    n, m = map(int, input().split())
    graph = defaultdict(list)
    L = [0] * (n + 1)
    ans = 0
    for _ in range(m):
        a, b = map(int, input().split())
        graph[a].append(b)
        graph[b].append(a)
    for i in range(1, n + 1):
        ans = max(ans, dfs(graph, L, i) * len(graph[i]))
    print(ans)

if __name__ == "__main__":
