import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        scanner.nextLine();

        int[][] pc = new int[n][2];
        int[] partyVotes = new int[m];

        for (int i = 0; i < n; i++) {
            String[] input = scanner.nextLine().split(" ");
            int p = Integer.parseInt(input[0]);
            int c = Integer.parseInt(input[1]);
            pc[i][0] = p - 1;
            pc[i][1] = c;
            partyVotes[p - 1]++;
        }

        Arrays.sort(pc, Comparator.comparingInt(a -> a[1]));

        int minCost = Integer.MAX_VALUE;

        for (int votes = 0; votes <= n; votes++) {
            int[] partyVotesCopy = Arrays.copyOf(partyVotes, m);
            boolean[] dangerous = new boolean[m];
            boolean[] used = new boolean[n];
            int curCost = 0;

            for (int i = 0; i < n; i++) {
                if (partyVotesCopy[pc[i][0]] >= votes && pc[i][0] != 0) {
                    curCost += pc[i][1];
                    partyVotesCopy[0]++;
                    partyVotesCopy[pc[i][0]]--;
                    dangerous[pc[i][0]] = partyVotesCopy[pc[i][0]] >= votes;
                    used[i] = true;
                }
            }

            for (int i = 0; i < n; i++) {
                if (partyVotesCopy[0] >= votes) {
                    break;
                }
                if (!used[i]) {
                    partyVotesCopy[0]++;
                    curCost += pc[i][1];
                }
            }

            minCost = Math.min(minCost, curCost);
        }

        System.out.println(minCost);
    }
}
