    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            String S = in.next();
            int n = S.length();

            int[] order = new int[26];
            int[] pos = new int[26];

            for (int i = 0; i < 26; ++i) {
                order[i] = i;
                pos[i] = 0;
            }

            int[] all = new int[26 * n];
            int cnt = 0;

            int tconf = 0;
            for (int i = 1; i <= n + 1; ++i) {
                int x = i <= n ? S.charAt(i - 1) - 'a' : 26;
                int conf = 0;
                for (int j = 0; j < 26; ++j) {
                    all[cnt++] = conf;
                    conf |= 1 << order[j];
                    if (order[j] == x || pos[order[j]] == 0) break;
                }
                if (x < 26) {
                    tconf |= 1 << x;
                    int p = 0;
                    while (order[p] != x) ++p;
                    while (p > 0) {
                        order[p] = order[p - 1];
                        --p;
                    }
                    order[0] = x;
                    pos[x] = i;
                }
            }
            Arrays.sort(all, 0, cnt);

            int q = in.nextInt();
            while (q-- > 0) {
                String P = in.next();
                int conf = 0;
                for (int i = 0; i < P.length(); ++i) {
                    conf |= 1 << P.charAt(i) - 'a';
                }
                int p1 = -1, p2 = -1, step;
                for (step = 1; step < cnt; step *= 2) ;
                for (; step > 0; step /= 2) {
                    if (p1 + step < cnt && all[p1 + step] < conf)
                        p1 += step;
                    if (p2 + step < cnt && all[p2 + step] <= conf)
                        p2 += step;
                }

                out.println(conf == tconf ? 1 : p2 - p1);
            }
        }

