					// try again with larger pointer
					pointers[i] = Math.max(colorCount[i]/(setSize+1),pointers[i]+1); 
					i--;
					// all sets have been checked
				}else if(i == colorCount.length - 1){
					done = true;
				}
			}
		}
		long totalSets = 0;
		for (int i = 0; i < pointers.length; i++) {
			totalSets += pointers[i];
		}
