import java.util.Scanner;

public class Main {
    private static final long P = 1000000007;

    private static long fpow(long b, long p) {
        p %= (P - 1);
        long r = 1;
        while (p > 0) {
            if ((p & 1) == 1) {
                r = (r * b) % P;
            }
            b = (b * b) % P;
            p >>= 1;
        }
        return r;
    }

