bool isPrime(int x) {
    int top = static_cast<int>(std::sqrt(x)) + 1;
    for (int a = 2; a <= top; a++) {
        if (x % a == 0) return false;
    }
    return true;
}

bool isPal(const std::string& rev) {
    int N = rev.length() / 2;
    for (int a = 0; a < N; a++) {
        if (rev[a] != rev[rev.length() - 1 - a]) return false;
    }
    return true;
}

