class Solution:
    def letterCombinations(self, digits: str) -> List[str]:
        if not digits:
            return []

        phone_map = {
            '2': 'abc',
            '3': 'def',
            '4': 'ghi',
            '5': 'jkl',
            '6': 'mno',
            '7': 'pqrs',
            '8': 'tuv',
            '9': 'wxyz'
        }

        def backtrack(combination, next_digits):
            if not next_digits:
                result.append(combination)
                return

            for letter in phone_map[next_digits[0]]:
                backtrack(combination + letter, next_digits[1:])

        result = []
        backtrack("", digits)
        return result
```

## Problem 8: [Problem Statement](https://leetcode.com/problems/rotate-image/)
