        in.open(inputFileName);
        out.open(outputFileName);
    }

    string readString() {
        while (tok.empty()) {
            string line;
            getline(in, line);
            if (line.empty()) return "";
            tok = line;
        }
        string token = tok.substr(0, tok.find(' '));
        tok.erase(0, tok.find(' ') + 1);
        return token;
    }

