		for (int i = 0; i < students; i++)
			arch[i] = new int[] { 0, -1, -1 };

		for (int i = 0; i < pairs; i++) {
			int a = in.nextInt() - 1;
			int b = in.nextInt() - 1;
			arch[a][++arch[a][0]] = b;
			arch[b][++arch[b][0]] = a;
		}

		int answer = 0;
		boolean[] visited = new boolean[students];
		for (int i = 0; i < students; i++)
			if (!visited[i] && arch[i][0] == 2) {
				int ar1 = arch[i][1];
				int ar2 = arch[i][2];

				// odd ring
				int nodesInARing = 2;
				boolean ok = true;
				int prev = i;

				while (true) {
					nodesInARing++;

					if (arch[ar1][0] != 2) {
						ok = false;
						break;
					}

					if (arch[ar1][1] + arch[ar1][2] - prev != ar2) {
						int temp = ar1;
						ar1 = arch[ar1][1] + arch[ar1][2] - prev;
						prev = temp;
					} else {
						break;
					}
				}

				if (ok && nodesInARing % 2 == 1) {
					answer++;
					ar1 = arch[i][1];
					prev = i;
					while (!visited[ar1]) {
						visited[ar1] = true;
						int temp = ar1;
						ar1 = arch[ar1][1] + arch[ar1][2] - prev;
						prev = temp;
					}
				}
				visited[i] = true;
			}


