        std::vector<double> cur_prob(N, 1.0);
        double cur_exp = 0;
        for (int i = 0; i < 200000; i++) {
            std::vector<double> bp(N);
            for (int j = 0; j < N; j++) {
                bp[j] = prob[j] * cur_prob[j] / (1 - cur_prob[j] + 1e-100);
