from collections import defaultdict

def dfs(graph, node, parent, visited, par, cyc):
    visited[node] = True
    for neighbor in graph[node]:
        if visited[neighbor]:
            if neighbor != parent and parent != 0:
                if par[neighbor][node] or par[node][neighbor]:
                    continue
                par[neighbor][node] = par[node][neighbor] = True
                cyc += 1
        else:
            dfs(graph, neighbor, node, visited, par, cyc)

def solve(n, m, edges):
    graph = defaultdict(list)
    par = [[False] * 102 for _ in range(102)]
    visited = [False] * 102
    cyc = 0

    for x, y in edges:
        graph[x].append(y)
        graph[y].append(x)

    dfs(graph, 1, 0, visited, par, cyc)

