#include <unordered_map>

int main() {
    int n;
    std::cin >> n;

    std::vector<int> nums(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> nums[i];
    }

    std::unordered_map<int, std::vector<int>> freqs;

    int _max = -1;
    for (int i = 0; i < n; ++i) {
        freqs[nums[i]].push_back(i + 1);
        _max = std::max(_max, static_cast<int>(freqs[nums[i]].size()));
    }

    int start = 1;
    int end = n;
    int length = end - start;
    for (const auto& pair : freqs) {
        if (pair.second.size() == _max) {
            if (pair.second.back() - pair.second.front() < length) {
                start = pair.second.front();
                end = pair.second.back();
                length = end - start;
            }
        }
    }

    std::cout << start << " " << end << std::endl;

    return 0;
}
