    std::cin >> n;
    int b, _;
    std::cin >> b >> _;
    std::vector<int> heap;
    std::vector<std::pair<int, int>> heap2;
    for (int i = 0; i < n - 1; i++) {
        int t, w;
        std::cin >> t >> w;
        if (t > b) {
            heap.push_back(w + 1 - t);
        } else {
            heap2.push_back({-t, -w});
        }
    }
    std::make_heap(heap.begin(), heap.end());
    std::make_heap(heap2.begin(), heap2.end(), [](const std::pair<int, int>& a, const std::pair<int, int>& b) {
        return a.first < b.first;
    });
    int ans = heap.size() + 1;
    while (!heap.empty()) {
        int need = heap.front();
        if (need > b) {
            break;
        }
        b -= need;
        std::pop_heap(heap.begin(), heap.end());
        heap.pop_back();
        while (!heap2.empty() && -heap2.front().first > b) {
            std::pair<int, int> p = heap2.front();
            heap2.erase(heap2.begin());
            int t = -p.first, w = -p.second;
            heap.push_back(w + 1 - t);
            std::push_heap(heap.begin(), heap.end());
        }
