std::string f(const std::vector<int>& l, const std::vector<int>& r) {
    std::unordered_map<int, std::vector<int>> cnts;
    std::vector<int> lmax(l.size(), 0);
    std::vector<int> rmax(l.size(), 0);
    for (int i = 0; i < l.size(); ++i) {
        cnts[l[i] + r[i]].push_back(i);
    }
    int mx = l.size();
    std::vector<int> ans(l.size(), 0);
    for (const auto& pair : cnts) {
        for (int ind : pair.second) {
            if (lmax[ind] == l[ind] && rmax[ind] == r[ind]) {
                ans[ind] = mx;
            } else {
                return "NO";
