                rmax[j] += 1;
            }
            for (int j = l.size() - 1; j > ind; --j) {
                lmax[j] += 1;
            }
        }
        mx -= 1;
    }
    std::cout << "YES" << std::endl;
    for (int num : ans) {
        std::cout << num << " ";
    }
    std::cout << std::endl;
    return "";
