from typing import List
from collections import defaultdict
from sortedcontainers import SortedSet

def min_cost_to_rearrange(arr: List[int], k: int) -> int:
    n = len(arr)
    nxt = [n + 1] * (n + 1)
    pos = defaultdict(int)
    have = defaultdict(int)
    s = SortedSet()

    for i in range(n, 0, -1):
        if arr[i] not in pos:
            nxt[i] = n + 1
        else:
            nxt[i] = pos[arr[i]]
        pos[arr[i]] = i

    cost = 0
    have_ctr = 0

    for i in range(1, n + 1):
        if have[arr[i]]:
            s.remove((nxt[i], arr[i]))
            s.add((nxt[i], arr[i]))
            continue
        cost += 1
        if have_ctr < k:
            have_ctr += 1
            have[arr[i]] = 1
            s.add((nxt[i], arr[i]))
            continue
        which = s[-1][1]
        have[which] = 0
        s.pop()
        have[arr[i]] = 1
        s.add((nxt[i], arr[i]))

    return cost

