		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		int[] a = sc.nexIntArray();
		int ans = 0;
		for(int i = 0; i < n-2;i++)
		{
			if(a[i]!=a[i+1] && a[i+1]!=a[i+2])
			{
				int j = i+2;
				while(j<n)
				{
					if(a[j]!=a[j-1]&&a[j-1]!=a[j-2])++j;
					else break;
				}
				--j;
				int len = j-i+1;
				if(a[i]==a[j])
				{
					ans = Math.max(ans, len/2);
					for (int k = i; k<=j; k++) 
						a[k] = a[i];
				}
				else
				{
					ans = Math.max(ans,len/2-1);
					for (int k = i; k<=j; k++) 
						a[k] = k-i<len/2? a[i] : a[j];
				}
			}
		}
		System.out.println(ans);
		StringBuilder sb = new StringBuilder();
		for(int i : a)sb.append(i+" ");
		System.out.println(sb);
	}
